"""Verification of the twin's building blocks. None of these tests needs a downloaded dataset."""
import numpy as np
import pandas as pd

from twin import core, hybrid, synth
from twin.data import folds, meal_macros


def toy_patient(days=4, seed=0, theta=(105.0, 3e-4, 0.03, 200.0, 8e-4)):
    """A patient generated by the twin's own equations with known parameters."""
    rng, T = np.random.default_rng(seed), days * 288
    meals = pd.DataFrame([{"idx": d * 288 + h * 12 + int(rng.integers(0, 6)), "kind": "meal", "carbs": float(rng.uniform(30, 90)),
                           "protein": 15.0, "fat": 10.0, "fiber": 4.0} for d in range(days) for h in (8, 13, 20)])
    mets = np.full(T, 1.2)
    for d in range(days):
        mets[d * 288 + 13 * 12 + 4:d * 288 + 13 * 12 + 8] = 3.5  # a walk after lunch
    p = {"id": "TOY", "cohort": "toy", "group": "T2D", "dt": 5, "static": {"weight_kg": 70.0}, "g": np.zeros(T), "mets": mets,
         "hr": np.full(T, 70.0), "tod": (np.arange(T) + 1) * 5 / 60 % 24, "meals": meals}
    gb, phi, k, c, bex = theta
    ctx, A = core.meal_ctx(p, np.arange(T)), core.activity(mets, 5)
    G, X, Z, D = np.array([gb]), np.zeros(1), np.zeros(1), np.zeros(1)
    for i in range(T):
        ra = core.meal_ra(np.array([k]), c / 70.0, tuple(x[i] for x in ctx), core.SLOW0, 0, 5)
        G, X, Z, D = core.step(G, X, Z, D, gb, phi, bex, ra, A[i], 5)
        p["g"][i] = G[0] + rng.normal(0, 2.0)
    return p


def test_every_gram_of_carbohydrate_is_absorbed_once():
    ctx = (np.array([60.0]), np.zeros((1, 5)), np.array([0.0]))
    total = sum(core.meal_ra(np.array([0.03]), 1.0, ctx, core.SLOW0, j, 5)[0] * 5 for j in range(400))
    assert abs(total - 60.0) < 1e-3


def test_fasting_twin_rests_at_basal_glucose():
    G, X, Z, D = np.array([100.0]), np.zeros(1), np.zeros(1), np.zeros(1)
    for _ in range(100):
        G, X, Z, D = core.step(G, X, Z, D, 100.0, 2e-4, 5e-4, 0.0, 0.0, 5)
    assert abs(G[0] - 100.0) < 1e-9


def test_event_is_fifteen_sustained_minutes_above_180():
    assert not core.sustained(np.array([170, 185, 190, 185, 170, 170]))      # 15 min needs four 5-min readings
    assert core.sustained(np.array([170, 185, 190, 185, 181, 170]))
    assert core.first_sustained(np.array([170, 185, 190, 185, 181, 170])) == 1
    assert core.sustained(np.array([170, 185, 190, 170]), dt=15)             # two 15-min readings


def test_nothing_after_the_origin_reaches_a_forecast():
    """Leakage guard: rewrite everything after bin i; the twin state and every feature at i must not move."""
    p, i = toy_patient(), 700
    q = dict(p)
    q["g"], q["mets"], q["hr"] = p["g"].copy(), p["mets"].copy(), p["hr"].copy()
    q["g"][i + 1:] += 80.0
    q["mets"][i + 1:] = 6.0
    q["hr"][i + 1:] = 150.0
    q["meals"] = p["meals"].assign(carbs=np.where(p["meals"]["idx"] > i, 300.0, p["meals"]["carbs"]))
    mu, sd = core.PRIOR_MU, core.PRIOR_SD
    (S1, L1, _), (S2, L2, _) = core.assimilate(p, mu, sd), core.assimilate(q, mu, sd)
    assert np.array_equal(S1[:i + 1], S2[:i + 1]) and np.array_equal(L1[:i + 1], L2[:i + 1])
    o = np.array([i - 30, i])
    pd.testing.assert_frame_equal(hybrid.raw_features(p, o).drop(columns=hybrid.STATIC), hybrid.raw_features(q, o).drop(columns=hybrid.STATIC))
    assert np.array_equal(core.rollout(p, o, S1, L1, 24), core.rollout(q, o, S2, L2, 24))


def test_filter_learns_the_patient_from_a_wrong_prior():
    theta = (105.0, 3e-4, 0.03, 200.0, 8e-4)
    p = toy_patient(days=6, theta=theta)
    mu = core.PRIOR_MU + np.array([0.25, -1.0, 0.0, 0.5, 0.0])  # prior: higher basal, weaker insulin response, more carb-sensitive
    S, L, _ = core.assimilate(p, mu, np.array([0.2, 1.0, 0.3, 0.5, 0.5]))
    true_rise = core.standard_meal_rise(np.log([theta]), 70.0)[0]
    prior_rise = core.standard_meal_rise(mu[None], 70.0)[0]
    post_rise = core.standard_meal_rise(L[-288:].mean(0), 70.0).mean()
    assert abs(np.exp(L[-288:, :, 0].mean()) - 105.0) < 8.0
    assert abs(post_rise - true_rise) < 0.35 * abs(prior_rise - true_rise)  # most of the prior error is gone


def test_twin_coasts_through_a_sensor_gap():
    p = toy_patient()
    p["g"][400:440] = np.nan
    S, L, innov = core.assimilate(p, core.PRIOR_MU, core.PRIOR_SD)
    assert np.isfinite(S).all() and np.isnan(innov[400:440]).all()
    assert S[420, :, 0].std() > S[399, :, 0].std()  # and it knows it is less sure


def test_whatif_changes_only_the_future_and_in_the_right_direction():
    p = toy_patient()
    i = int(p["meals"]["idx"].iloc[4])
    S, L, _ = core.assimilate(p, core.PRIOR_MU, core.PRIOR_SD)
    q = core.scenario(p, i, carb_scale=0.5)
    assert np.array_equal(q["mets"][:i + 1], p["mets"][:i + 1]) and (q["meals"]["idx"] <= i).all()
    peak = lambda r: core.rollout(r, [i], S, L, 36, conditioned=True).max(-1).mean()
    base = peak(core.scenario(p, i))
    assert peak(q) < base - 5                                   # half the carbohydrate, lower peak
    assert peak(core.scenario(p, i, walk_min=20)) < base        # a walk after the meal, lower peak
    assert peak(core.scenario(p, i, add_meal=(40, 5, 5, 1))) > base + 5


def test_recommendation_is_the_least_effort_action_under_the_risk():
    p = toy_patient()
    i = int(p["meals"]["idx"].iloc[4])
    S, L, _ = core.assimilate(p, core.PRIOR_MU, core.PRIOR_SD)
    k, pr = core.recommend(p, i, S, L)
    assert pr[6] <= pr[0] and pr[3] <= pr[0]                    # less food never raises the twin's risk
    assert core.recommend(p, i, S, L, risk=1.01)[0] == 0         # nothing to fix: no advice
    assert core.recommend(p, i, S, L, risk=0.0)[0] == pr.argmin()  # nothing gets under the bar: the safest action
    for r in (0.05, 0.2, 0.5):
        k, _ = core.recommend(p, i, S, L, risk=r)
        if pr[0] >= r and (pr < r).any():
            assert pr[k] < r and core.EFFORT[k] == core.EFFORT[pr < r].min()


def test_conformal_intervals_cover_and_adapt():
    rng = np.random.default_rng(0)
    cal = np.sort(np.abs(rng.standard_normal(2000)))
    test = np.abs(rng.standard_normal(5000))
    assert abs((test <= hybrid.quantile(cal, 0.9)).mean() - 0.9) < 0.02
    shifted = 1.6 * test                                        # errors grow: plain split conformal now under-covers
    assert (shifted <= hybrid.quantile(cal, 0.9)).mean() < 0.75
    assert abs((shifted <= hybrid.aci(cal, shifted, 0.1, gamma=0.02))[500:].mean() - 0.9) < 0.03  # ACI recovers


def test_alert_replay_counts_events_and_false_alerts():
    d = pd.DataFrame({"id": "A", "t": np.arange(0, 600, 15.0), "g0": 120.0, "p": 0.0, "evt2h": 0.0, "lead": np.nan})
    d.loc[10:13, ["evt2h", "lead"]] = [[1, 60], [1, 45], [1, 30], [1, 15]]  # one event, seen from four origins
    d.loc[[11, 30], "p"] = 0.9                                             # one true alert, one false
    r = hybrid.alerts(d, "p", 0.5)
    assert r["events"] == 1 and r["sensitivity"] == 1.0 and r["median_lead_min"] == 45
    assert abs(r["false_per_day"] - 1 / (585 / 1440)) < 1e-9


def test_free_text_meals_become_macros():
    carbs, protein, fat, fibre = meal_macros("Rice 100 g\nVegetable 150 g\nBeef 50 g")
    assert abs(carbs - (26 + 6 + 0.5)) < 1e-6 and protein > 10
    assert meal_macros("data not available").sum() == 0


def test_folds_never_split_a_patient():
    P = [{"group": g} for g in ["a"] * 11 + ["b"] * 9]
    f = folds(P, 5)
    assert sorted(np.concatenate(f)) == list(range(20)) and len(set(np.concatenate(f))) == 20


def test_generator_is_reproducible_and_counterfactuals_are_exact():
    a, b = synth.generate(n=2, days=2, seed=3), synth.generate(n=2, days=2, seed=3)
    assert np.array_equal(a[0]["g"], b[0]["g"], equal_nan=True) and a[1]["static"] == b[1]["static"]
    sp, plan = a[0]["truth"], a[0]["plan"]
    g0 = synth.simulate(sp, plan)[0]
    plan2 = dict(plan, meals=[dict(m, carbs=m["carbs"] * 0.5) if j == 1 else m for j, m in enumerate(plan["meals"])])
    g1 = synth.simulate(sp, plan2)[0]
    t = plan["meals"][1]["t"]
    assert np.array_equal(g0[:t], g1[:t]) and g1[t:t + 180].max() < g0[t:t + 180].max()


def test_regional_cohort_fills_its_prevalence_and_eats_its_plates():
    from twin.india import REGIONS, menu, plate
    P = synth.generate(n=10, days=3, region="south")
    R = REGIONS["south"]
    assert [p["group"] for p in P].count("T2D") == round(10 * R["t2d"]) and all(p["id"].startswith("INS-") for p in P)
    for p in P:
        names = {n for opts in menu("south", p["static"]["state"]).values() for n, _, _ in opts}
        assert p["static"]["state"] in R["states"] and {m["name"] for m in p["plan"]["meals"]} <= names
    m = plate([("ASC113", 1), ("ASC167", 1)])  # rice and sambar: label carbohydrate = available + fibre; GI between dal and rice
    assert abs(m["carbs"] - (77.2 + 3.7 + 27.2 + 9.1)) < 1e-9 and 32 < m["gi"] < 73
    sp, plan = P[0]["truth"], P[0]["plan"]  # a higher-GI version of the same meal peaks higher
    j = next(j for j, x in enumerate(plan["meals"]) if x["kind"] == "lunch")
    fast = dict(plan, meals=[dict(x, gi=98) if k == j else x for k, x in enumerate(plan["meals"])])
    t = plan["meals"][j]["t"]
    assert synth.simulate(sp, fast)[0][t:t + 180].max() > synth.simulate(sp, dict(plan, meals=[dict(x, gi=40) if k == j else x for k, x in enumerate(plan["meals"])]))[0][t:t + 180].max()


def test_dashboard_renders_and_answers_a_whatif():
    """Runs app.py headless on the synthetic cohort (shipped models, no download)."""
    from pathlib import Path

    from streamlit.testing.v1 import AppTest

    at = AppTest.from_file(str(Path(__file__).parents[1] / "app.py"), default_timeout=300).run()
    assert not at.exception and len(at.metric) == 6
    assert any(m.value.startswith("**Suggested change**") for m in at.markdown)  # opens at a meal: the twin advises
    walk = next(s for s in at.slider if s.label.startswith("Walk after"))
    walk.set_value(30).run()
    assert not at.exception and at.metric[4].delta.startswith(("-", "+"))  # the what-if now reports a change
